"""SQLAlchemy model for proactive notifications, briefings, and contextual check-ins."""

import uuid
from datetime import datetime
from typing import Any, Dict, Optional
from sqlalchemy import (
    DateTime,
    ForeignKey,
    Index,
    JSON,
    String,
    Text,
    Uuid,
)
from sqlalchemy.orm import Mapped, mapped_column, relationship
from app.models.base import Base, TimestampMixin, UUIDPrimaryKeyMixin, utcnow


class ProactiveNotification(Base, UUIDPrimaryKeyMixin, TimestampMixin):
    """Proactive interaction, reminder, check-in, or briefing generated by the assistant."""

    __tablename__ = "proactive_notifications"

    user_id: Mapped[uuid.UUID] = mapped_column(
        Uuid(as_uuid=True),
        ForeignKey("users.id", ondelete="CASCADE"),
        index=True,
        nullable=False,
    )
    notification_type: Mapped[str] = mapped_column(
        String(64),
        index=True,
        nullable=False,
        comment="MEAL_CHECK_IN, ROUTINE_REMINDER, TASK_DEADLINE, MORNING_BRIEFING, EVENING_BRIEFING, SUGGESTION",
    )
    channel: Mapped[str] = mapped_column(
        String(32),
        default="IN_APP",
        nullable=False,
        comment="IN_APP, AUDIO, SYSTEM",
    )
    priority: Mapped[str] = mapped_column(
        String(16),
        default="NORMAL",
        nullable=False,
        comment="LOW, NORMAL, HIGH, URGENT",
    )
    title: Mapped[str] = mapped_column(
        String(255),
        nullable=False,
    )
    content: Mapped[str] = mapped_column(
        Text,
        nullable=False,
    )
    context_data: Mapped[Optional[Dict[str, Any]]] = mapped_column(
        JSON,
        nullable=True,
        comment="Structured evidence, suggested actions, reference entity IDs",
    )
    status: Mapped[str] = mapped_column(
        String(32),
        default="DISPATCHED",
        index=True,
        nullable=False,
        comment="PENDING, DISPATCHED, SUPPRESSED_QUIET_HOURS, SUPPRESSED_THROTTLED, READ, DISMISSED",
    )
    suppression_reason: Mapped[Optional[str]] = mapped_column(
        String(128),
        nullable=True,
    )
    deduplication_key: Mapped[Optional[str]] = mapped_column(
        String(128),
        index=True,
        nullable=True,
        comment="Deterministic key e.g. meal_check_in:2026-10-18 or routine:{occ_key}",
    )
    dispatched_at: Mapped[Optional[datetime]] = mapped_column(
        DateTime(timezone=True),
        nullable=True,
    )
    read_at: Mapped[Optional[datetime]] = mapped_column(
        DateTime(timezone=True),
        nullable=True,
    )
    dismissed_at: Mapped[Optional[datetime]] = mapped_column(
        DateTime(timezone=True),
        nullable=True,
    )

    __table_args__ = (
        Index("ix_proactive_notifications_user_status", "user_id", "status"),
        Index("ix_proactive_notifications_user_created_at", "user_id", "created_at"),
        Index("ix_proactive_notifications_dedup", "user_id", "deduplication_key"),
    )

    def __repr__(self) -> str:
        return f"<ProactiveNotification(id={self.id}, user_id={self.user_id}, type={self.notification_type}, status={self.status})>"
